// Props of the BrandShort composition. Generated by .claude/skills/siri2moon-short/scripts/build-props.mjs
// from content/<dir>/short.json — do not write by hand.

export type ThemeName = 'lucifer' | 'siri2moon';

/** Virtual camera frame over the footage, in the page's CSS px at capture time (already divided by dpr). */
export type FrameKey = { f: number; cx: number; cy: number; zoom: number };

/** One line in a terminal scene. Text can be colored with {green}…{/}, see Terminal.tsx. */
export type TerminalItem = {
  kind: 'cmd' | 'out';
  text: string;
  /** Frame (within the scene) where the command starts typing / the line prints. */
  from: number;
  /** Command: characters typed per frame. */
  perFrame: number;
  prompt: string;
};

export type TerminalSpec = { title: string; fontSize: number; items: TerminalItem[] };

/** Motion graphics scene (Motion.tsx), with data already converted to frames. */
export type MotionSpec =
  | { type: 'split'; before: string; after: string; labels: [string, string] }
  | {
      type: 'wave';
      /** File name shown at the top of the frame. */
      file: string;
      /** Amplitude 0–1 of each column, covering the whole audio window. */
      peaks: number[];
      /** Segments kept, as fractions (0–1) of the window. */
      keep: [number, number][];
      seconds: number;
      keptSeconds: number;
      /** Frame (within the scene) where the silences start closing up. */
      cutAt: number;
      labels: { silence: string; cut: string };
    }
  | { type: 'words'; words: { text: string; from: number; to: number }[]; tag: string }
  | { type: 'pipeline'; steps: { icon: string; title: string; sub: string; at: number }[] }
  /** Types the prompt, then the picture appears below it. */
  | { type: 'prompt'; label: string; text: string; image: string; typeEnd: number; reveal: number }
  /** A grid of pictures appearing one by one, with a summary badge at the end of the scene. */
  | { type: 'gallery'; images: string[]; every: number; badge: string }
  /** A spoken line turning into a waveform as the voice plays, with its measured length. */
  | { type: 'speak'; label: string; text: string; peaks: number[]; seconds: number; tag: string }
  /** Document pages (a PDF rendered to images) fly up and fan out, first page in front. */
  | { type: 'pages'; pages: string[]; every: number; badge: string; badgeAt: number }
  /** Timeline bar of the script's acts + a music lane, swept by a playhead; the card below names the current act. */
  | {
      type: 'acts';
      label: string;
      seconds: number;
      /** Frames where the playhead starts / reaches the end of the bar. */
      sweep: [number, number];
      /** from/to as fractions (0–1) of the whole script. */
      acts: { name: string; from: number; to: number; icon: string; job: string; color: string }[];
      music: { name: string; from: number; to: number; silent: boolean }[];
    }
  /** A serious calculation: rows appear one by one, numbers count up, then a conclusion is stamped. */
  | {
      type: 'calc';
      label: string;
      rows: { label: string; at: number; prefix: string; value: number; decimals: number; dec: string; group: string; suffix: string }[];
      stamp: string;
      stampAt: number;
    }
  /** A real status line (ANSI output of a script run at build time), grouped at │.
   *  quota = consecutive states, with a big quota number in exactly the color the script prints;
   *  explain = each group lights up with a line of explanation. */
  | {
      type: 'statusline';
      mode: 'quota' | 'explain';
      label: string;
      states: { at: number; groups: StatusSpan[][]; quota: { left: number; color: string; reset: string } | null }[];
      rows: { label: string; at: number }[];
    };

export type StatusSpan = { t: string; c: string };

/** A label pointing at a spot on the video in the phone layout: y in px of the source video. */
export type Callout = { from: number; y: number; side: 'left' | 'right'; text: string };

export type ShortScene = {
  id: string;
  from: number;
  dur: number;
  /** Path inside content/, e.g. "<dir>/footage/hero.mp4", or a .png/.jpg image. */
  src: string;
  kind: 'video' | 'image' | 'terminal' | 'motion';
  terminal?: TerminalSpec;
  motion?: MotionSpec;
  callouts?: Callout[];
  /** Scene audio (a real voice, clip audio, or ElevenLabs narration): background music ducks while it plays.
   *  delay = frames to wait from the start of the scene before the audio starts.
   *  dur = frames the audio lasts (narration); when set, the music ducks only during it instead of the whole scene.
   *  duck = music level while it plays (default 0.25). */
  voice?: { src: string; startFrom: number; volume: number; delay?: number; dur?: number; duck?: number } | null;
  /** Frames skipped at the start of the footage. */
  startFrom: number;
  rate: number;
  /** full = fills the vertical frame; card = rounded window panning along `keys` over a blurred copy of the footage;
   *  phone = vertical video in a phone frame, leaving room for captions and side labels. */
  layout: 'full' | 'card' | 'phone';
  keys: FrameKey[];
  /** Footage size (px) and dpr at capture time, to convert keys to video px. */
  size: [number, number];
  dpr: number;
  lines: string[];
  big: boolean;
};

export type ShortSfx = { src: string; from: number; dur: number; volume: number };

export type ShortProps = {
  id: string;
  theme: ThemeName;
  lang: string;
  fps: number;
  durationInFrames: number;
  chip: { title: string; subtitle: string } | null;
  /** Multi-episode series: label "EP 1/5", name = series name. */
  series: { label: string; name: string } | null;
  scenes: ShortScene[];
  outro: {
    from: number;
    dur: number;
    scene: ShortScene | null;
    title: string;
    subtitle: string;
    chips: string[];
    link: string | null;
    linkIcon: 'github' | 'web';
    /** Darkness laid over the background footage while the logo shows (0–1). */
    dim: number;
  } | null;
  endcard: { from: number; dur: number; follow: string; lines: string[]; /** Series: teaser for the next episode. */ next: string | null };
  /** Background music: the synthesized track, or a music file cut from the downbeat at `trimBefore` (frames). */
  bgm: { src: string; volume: number; trimBefore: number; loop: boolean } | null;
  bpm: number;
  sfx: ShortSfx[];
};
